foreach (int free in new[] { 0, 2, 5 })
{
    try
    {
        Reserve(3, free);
        Console.WriteLine("Бронь принята");
    }
    catch (SeatLimitException error) when (error.Free == 0)
    {
        Console.WriteLine("Мест больше нет");
    }
    catch (SeatLimitException error)
    {
        Console.WriteLine($"Можно взять {error.Free}");
    }
}

static void Reserve(int requested, int free)
{
    if (requested > free)
        throw new SeatLimitException(free);
}

sealed class SeatLimitException : Exception
{
    public int Free { get; }

    public SeatLimitException(int free) : base("Недостаточно мест")
    {
        Free = free;
    }
}

