using System.Xml;

var board = new XmlDocument();
board.LoadXml("""
    <board>
      <line id="A"><last>Парк</last></line>
      <line id="B"><last>Стадион</last></line>
    </board>
    """);
if (board.SelectSingleNode("/board/line[@id='B']/last") is XmlElement last)
{
    Console.WriteLine(last.InnerText);
    last.InnerText = "Депо";
    last.SetAttribute("changed", "yes");
}
Console.WriteLine(board.SelectSingleNode("/board/line[@id='B']")?.OuterXml);

using System.Xml.Linq;
using System.Xml.Serialization;

var serializer = new XmlSerializer(typeof(Ticket));
using var input = new StringReader("<ticket row='3'><holder>Ася</holder></ticket>");
if (serializer.Deserialize(input) is Ticket ticket)
{
    Console.WriteLine($"{ticket.Holder}, ряд {ticket.Row}");
    ticket.Row++;
    using var output = new StringWriter();
    serializer.Serialize(output, ticket);
    var saved = XElement.Parse(output.ToString());
    Console.WriteLine(saved.Attribute("row")?.Value);
}

[XmlRoot("ticket")]
public class Ticket
{
    [XmlAttribute("row")]
    public int Row { get; set; }

    [XmlElement("holder")]
    public string Holder { get; set; } = "";
}

