using var ready = new AutoResetEvent(false);
string packet = "";
string receipt = "";

ThreadStart read = () =>
{
    ready.WaitOne();
    receipt = "Получено " + packet;
};
ParameterizedThreadStart write = data =>
{
    if (data is string label) packet = label;
    ready.Set();
};
var reader = new Thread(read);
var writer = new Thread(write);
reader.Start();
writer.Start("чай");
reader.Join();
writer.Join();
Console.WriteLine(receipt);
Console.WriteLine(ready.WaitOne(0));

int count = 0;
using var bothRead = new Barrier(2);
var gate = new System.Threading.Lock();

RunPair(AddBroken);
Console.WriteLine(count);
count = 0;
RunPair(AddSafe);
Console.WriteLine(count);

void AddBroken()
{
    int old = Volatile.Read(ref count);
    bothRead.SignalAndWait();
    Volatile.Write(ref count, old + 1);
}
void AddSafe()
{
    lock (gate) { count++; }
}
static void RunPair(ThreadStart add)
{
    var first = new Thread(add);
    var second = new Thread(add);
    first.Start();
    second.Start();
    first.Join();
    second.Join();
}

object gate = new();
int stock = 0;
var smallBox = new Thread(() =>
{
    lock (gate) { stock += 3; }
});
var bigBox = new Thread(() =>
{
    bool entered = false;
    try
    {
        Monitor.Enter(gate, ref entered);
        stock += 4;
    }
    finally
    {
        if (entered) Monitor.Exit(gate);
    }
});
smallBox.Start();
bigBox.Start();
smallBox.Join();
bigBox.Join();
Console.WriteLine(stock);

using var mutex = new Mutex();
mutex.WaitOne();
try
{
    Console.WriteLine(TryFromWorker());
}
finally
{
    mutex.ReleaseMutex();
}
Console.WriteLine(TryFromWorker());

bool TryFromWorker()
{
    bool entered = false;
    var worker = new Thread(() =>
    {
        entered = mutex.WaitOne(0);
        if (entered) mutex.ReleaseMutex();
    });
    worker.Start();
    worker.Join();
    return entered;
}

using var places = new Semaphore(2, 2);
places.WaitOne();
places.WaitOne();
Console.WriteLine(places.WaitOne(0));

bool entered = false;
var visitor = new Thread(() =>
{
    places.WaitOne();
    try { entered = true; }
    finally { places.Release(); }
});
visitor.Start();
places.Release();
visitor.Join();
Console.WriteLine(entered);
places.Release();

