public sealed class Reading(int celsius) : DynamicObject
{
    public override bool TryGetMember(GetMemberBinder binder, out object? result)
    {
        if (binder.Name == "Fahrenheit")
        {
            result = celsius * 9.0 / 5.0 + 32;
            return true;
        }
        result = null;
        return false;
    }
}

