using System.Diagnostics;

using var own = Process.GetCurrentProcess();
Console.WriteLine(own.Id == Environment.ProcessId ? "Это наш процесс" : "Другой PID");

var start = new ProcessStartInfo("dotnet")
{
    UseShellExecute = false,
    RedirectStandardOutput = true
};
start.ArgumentList.Add("--version");
using var child = Process.Start(start) ?? throw new InvalidOperationException("Не удалось запустить dotnet");
string version = child.StandardOutput.ReadToEnd().Trim();
child.WaitForExit();
Console.WriteLine(child.ExitCode == 0 && version.Length > 0 ? "SDK ответил" : "Проверь SDK");

using System.Runtime.Loader;

var original = typeof(Workshop.Label);
var context = new AssemblyLoadContext("Preview", isCollectible: true);
using (var file = File.OpenRead(original.Assembly.Location))
{
    var copy = context.LoadFromStream(file);
    var copiedType = copy.GetType("Workshop.Label", throwOnError: true)!;
    Console.WriteLine(AssemblyLoadContext.GetLoadContext(copy)?.Name);
    Console.WriteLine(copiedType.FullName == original.FullName);
    Console.WriteLine(copiedType == original);
    Console.WriteLine(copiedType.GetMethod("Caption")?.Invoke(null, null));
}
context.Unload();
Console.WriteLine("Выгрузка запрошена");

